<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;
class AdmissionDossierController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function show(Request $r,$id){$this->ok($r);$a=DB::table('admission_applicants')->find($id);abort_if(!$a,404);$applications=DB::table('admission_applications as ap')->join('admission_targets as t','t.id','=','ap.target_id')->join('admission_campaigns as c','c.id','=','ap.campaign_id')->join('specialties as sp','sp.id','=','t.specialty_id')->where('ap.applicant_id',$id)->select('ap.*','c.name as campaign_name','sp.code','sp.name as specialty')->get();$campaignIds=$applications->pluck('campaign_id')->unique();$requirements=DB::table('admission_document_requirements')->whereIn('campaign_id',$campaignIds)->where('active',1)->orderBy('sort_order')->get();$documents=DB::table('admission_documents')->where('applicant_id',$id)->get()->keyBy('requirement_id');$exams=DB::table('admission_exam_results as er')->join('admission_exams as e','e.id','=','er.exam_id')->join('admission_applications as ap','ap.id','=','er.application_id')->where('ap.applicant_id',$id)->select('er.*','e.name','e.min_score','e.max_score')->get();$messages=DB::table('admission_messages')->where('applicant_id',$id)->orderByDesc('id')->get();$required=$requirements->where('required',1);$accepted=$required->filter(fn($x)=>isset($documents[$x->id])&&$documents[$x->id]->status==='accepted')->count();$completeness=$required->count()?round($accepted*100/$required->count()):100;return view('admission.dossier',compact('a','applications','requirements','documents','exams','messages','completeness'));}
 public function requirement(Request $r){$this->ok($r);$d=$r->validate(['campaign_id'=>'required|exists:admission_campaigns,id','code'=>'required|string|max:80','name'=>'required|string|max:255','required'=>'nullable|boolean','file_required'=>'nullable|boolean','sort_order'=>'nullable|integer|min:0']);DB::table('admission_document_requirements')->updateOrInsert(['campaign_id'=>$d['campaign_id'],'code'=>$d['code']],['name'=>$d['name'],'required'=>$r->boolean('required'),'file_required'=>$r->boolean('file_required'),'sort_order'=>$d['sort_order']??0,'active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Требование к документам сохранено.');}
 public function moderate(Request $r,$document){$this->ok($r);$d=$r->validate(['status'=>'required|in:accepted,correction,rejected','moderation_note'=>'nullable|string|max:2000']);if(in_array($d['status'],['correction','rejected'])&&!trim($d['moderation_note']??''))abort(422,'Укажите причину возврата или отклонения.');$doc=DB::table('admission_documents')->find($document);abort_if(!$doc,404);DB::transaction(function()use($d,$doc,$r,$document){DB::table('admission_documents')->where('id',$document)->update($d+['moderated_by'=>$r->user()->id,'moderated_at'=>now(),'updated_at'=>now()]);if($d['status']!=='accepted')DB::table('admission_messages')->insert(['applicant_id'=>$doc->applicant_id,'user_id'=>$r->user()->id,'direction'=>'to_applicant','message'=>($d['status']==='correction'?'Документ возвращён на исправление: ':'Документ отклонён: ').$d['moderation_note'],'created_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Решение по документу сохранено.');}
 public function verify(Request $r,$id){$this->ok($r);$a=DB::table('admission_applicants')->find($id);abort_if(!$a,404);$campaignIds=DB::table('admission_applications')->where('applicant_id',$id)->pluck('campaign_id');$req=DB::table('admission_document_requirements')->whereIn('campaign_id',$campaignIds)->where(['active'=>1,'required'=>1])->pluck('id');$accepted=DB::table('admission_documents')->where('applicant_id',$id)->whereIn('requirement_id',$req)->where('status','accepted')->pluck('requirement_id')->unique();abort_if($accepted->count()<$req->unique()->count(),422,'Нельзя проверить личное дело: не все обязательные документы приняты.');DB::table('admission_applicants')->where('id',$id)->update(['portal_status'=>'verified','verified_at'=>now(),'updated_at'=>now()]);return back()->with('success','Личное дело проверено и зафиксировано.');}
}